import { t } from './i18n.mjs';
export function showSupportChoices({modal,close,pay,contact}){modal(`<div class="eyebrow">${t("A LITTLE HELP GOES A LONG WAY","MỘT CHÚT GIÚP ĐỠ, MỘT THAY ĐỔI LỚN","작은 도움이 큰 힘이 됩니다")}</div><h2>${t("How would you like to help?","Bạn muốn giúp theo cách nào?","어떤 방식으로 돕고 싶으신가요?")}</h2><p>${t("Offer support now or contact the card owner to learn more.","Chọn hỗ trợ ngay hoặc liên hệ chủ thẻ để tìm hiểu thêm.","바로 돕거나 카드 작성자에게 연락해 자세히 알아보세요.")}</p><div class="support-choice-list"><button id="card-choice-pay"><span>♡</span><div><strong>${t("Send money in the app","Gửi tiền giúp qua app","앱에서 후원금 보내기")}</strong><small>${t("In-app payments · Coming soon","Thanh toán trong ứng dụng · Sẽ được bổ sung sau","앱 내 결제 · 준비 중")}</small></div><b>→</b></button><button id="card-choice-contact"><span>✉</span><div><strong>${t("Notify and message the card owner","Gửi thông báo & nhắn tin","카드 작성자에게 알림과 메시지 보내기")}</strong><small>${t("Ask the card owner for more information","Hỏi chủ thẻ để có thêm thông tin đầy đủ","카드 작성자에게 자세한 정보 물어보기")}</small></div><b>→</b></button></div><p class="support-choice-note">${t("Preview mode: payments, notifications and messages to other people are unavailable.","Bản xây dựng: chưa có thanh toán, gửi thông báo hoặc tin nhắn đến người thật.","미리보기 모드에서는 결제하거나 다른 사람에게 알림 및 메시지를 보낼 수 없습니다.")}</p>`);document.querySelector('#card-choice-pay').onclick=()=>{close();pay();};document.querySelector('#card-choice-contact').onclick=()=>{close();contact();};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showSupportMessageStep({id,name,modal,toast}){let draft='';try{draft=JSON.parse(localStorage.getItem('debtfreelately-support-message-drafts')||'{}')[id]?.message||'';}catch{}
modal(`<div class="eyebrow">${t("A LITTLE KINDNESS, IN YOUR WORDS","GỬI CHÚT TỬ TẾ BẰNG LỜI CỦA BẠN","따뜻한 마음을 한마디로")}</div><h2>${t("A message to share a little hope.","Một lời nhắn để tiếp thêm hy vọng.","희망을 전하는 한마디.")}</h2><p>${t("You can leave a message at the end of the support process. Once payments are available, it will appear on the Wall of Gratitude alongside your name and contribution.","Phần lời nhắn ở cuối luồng hỗ trợ. Sau khi có thanh toán thật, lời nhắn sẽ đi cùng tên và số tiền người giúp trên Wall of Gratitude.","후원 절차 마지막에 메시지를 남길 수 있습니다. 결제가 가능해지면 감사의 벽에 이름과 후원 금액이 함께 표시됩니다.")}</p><div class="info-box">${t("Payments are still in development. Saving below keeps a draft on this device without sending a message or transferring money.","Bản xây dựng: thanh toán chưa được tích hợp. Lưu bên dưới chỉ tạo bản nháp trên thiết bị, chưa gửi lời nhắn hoặc chuyển tiền.","결제 기능은 준비 중입니다. 저장하면 기기에 초안이 남으며 메시지나 돈이 전송되지 않습니다.")}</div><form id="support-message-form"><label for="support-message">${t(`Send <strong>${esc(name)}</strong> a short note or a wish`,`Hãy gửi cho <strong>${esc(name)}</strong> một lời khuyên hoặc một lời chúc ngắn`,`<strong>${esc(name)}</strong>님에게 짧은 조언이나 응원을 전해 주세요`)}</label><textarea id="support-message" name="message" maxlength="200" placeholder="${t("Example: Take it one step at a time. I hope you get a fresh start soon!","Ví dụ: Từng bước một nhé, chúc bạn sớm có một khởi đầu mới!","예: 한 걸음씩 나아가세요. 곧 새로운 시작을 맞이하시길 응원합니다!")}">${esc(draft)}</textarea><div class="support-message-meta"><span>${t("Optional · Up to 200 characters","Không bắt buộc · Tối đa 200 ký tự","선택 사항 · 최대 200자")}</span><span id="support-message-count">${draft.length}/200</span></div><p class="support-message-hint">${t("A little encouragement can make a big difference.","Một lời động viên nhỏ cũng có thể tạo nên khác biệt lớn.","작은 응원 한마디가 큰 힘이 될 수 있습니다.")}</p><p id="support-message-status" class="form-error" role="status"></p><button class="dark">${t("Save message draft","Lưu lời nhắn nháp","메시지 초안 저장")}</button></form>`);
document.querySelector('#support-message').oninput=event=>document.querySelector('#support-message-count').textContent=event.target.value.length+'/200';document.querySelector('#support-message-form').onsubmit=event=>{event.preventDefault();const message=new FormData(event.target).get('message').trim();try{const key='debtfreelately-support-message-drafts',items=JSON.parse(localStorage.getItem(key)||'{}');items[id]={recipient:name,message,updatedAt:new Date().toISOString(),status:'draft'};localStorage.setItem(key,JSON.stringify(items));document.querySelector('#support-message-status').textContent=t("Draft saved on this device. No message or money was sent.","Đã lưu bản nháp trên thiết bị. Chưa gửi lời nhắn hoặc chuyển tiền.","이 기기에 초안을 저장했습니다. 메시지와 돈은 전송되지 않았습니다.");toast(t("Message draft saved.","Đã lưu lời nhắn nháp.","메시지 초안을 저장했습니다."));}catch{document.querySelector('#support-message-status').textContent=t("Could not save the draft. Try again.","Không lưu được bản nháp. Vui lòng thử lại.","초안을 저장할 수 없습니다. 다시 시도하세요.");}};
}
